cd /var/folders/4_/s6fbcjyn4b13xdxkd3lv0kw00000gn/T/arm-s22a-baseline-l4mgtnni; mkdir -p work; python3 - <<'E' | tee work/result.txt
import csv,collections
d='data/a-fanout/'
o=list(csv.DictReader(open(d+'orders.csv')));a=list(csv.DictReader(open(d+'accounts.csv')))
seg=collections.defaultdict(set)
for r in a:seg[r['account_id']].add(r['segment'])
print('accounts with >1 segment:',[k for k,v in seg.items() if len(v)>1])
q=[r for r in o if '2026-04-01'<=r['order_date']<='2026-06-30']
tot=collections.defaultdict(float);n=collections.Counter()
for r in q:
    s=next(iter(seg[r['account_id']]));tot[s]+=float(r['amount_usd']);n[s]+=1
print('correct',dict(tot),dict(n),'all',sum(tot.values()))
# naive fan-out join
naive=0
for r in q:
    for x in a:
        if x['account_id']==r['account_id'] and x['segment']=='Enterprise':naive+=float(r['amount_usd'])
print('naive join Enterprise',naive)
m=collections.defaultdict(float)
for r in q:
    if 'Enterprise' in seg[r['account_id']]:m[r['order_date'][:7]]+=float(r['amount_usd'])
print(dict(m))
E

